import { computed, DestroyRef, DOCUMENT, effect, inject, Injectable, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { NavigationEnd, Router } from '@angular/router';
import { filter, map } from 'rxjs';

export interface Crumb {
  readonly label: string;
  readonly link?: string;
}

type ThemeChoice = 'light' | 'dark';

const THEME_STORAGE_KEY = 'hero-ops-theme';
const DARK_QUERY = '(prefers-color-scheme: dark)';

const SECTION_LABELS: Readonly<Record<string, string>> = {
  dashboard: 'Dashboard',
  roster: 'Roster',
  missions: 'Missions',
  threats: 'Threats',
  recruit: 'Recruit',
  settings: 'Settings',
};

// Shell state: the theme choice and the breadcrumb trail. Component-scoped, provided by App.
@Injectable()
export class AppViewModel {
  private readonly document = inject(DOCUMENT);
  private readonly router = inject(Router);
  private readonly view = this.document.defaultView;
  // matchMedia is absent in jsdom and some embedded hosts, so it is optional here.
  private readonly systemQuery = this.view?.matchMedia?.(DARK_QUERY) ?? null;

  // null means the user has made no choice, so the system preference decides.
  private readonly choice = signal<ThemeChoice | null>(this.readStoredChoice());
  private readonly systemDark = signal(this.systemQuery?.matches ?? false);

  readonly dark = computed(() =>
    this.choice() === null ? this.systemDark() : this.choice() === 'dark',
  );

  private readonly url = toSignal(
    this.router.events.pipe(
      filter((event): event is NavigationEnd => event instanceof NavigationEnd),
      map((event) => event.urlAfterRedirects),
    ),
    { initialValue: this.router.url },
  );

  readonly crumbs = computed(() => this.crumbsFor(this.url()));

  constructor() {
    effect(() => {
      this.document.documentElement.classList.toggle('dark', this.dark());
    });

    const onSystemChange = (event: MediaQueryListEvent) => this.systemDark.set(event.matches);
    this.systemQuery?.addEventListener('change', onSystemChange);
    inject(DestroyRef).onDestroy(() => this.systemQuery?.removeEventListener('change', onSystemChange));
  }

  toggleTheme(): void {
    const next: ThemeChoice = this.dark() ? 'light' : 'dark';
    this.choice.set(next);
    this.view?.localStorage.setItem(THEME_STORAGE_KEY, next);
  }

  private readStoredChoice(): ThemeChoice | null {
    const stored = this.view?.localStorage.getItem(THEME_STORAGE_KEY);
    return stored === 'light' || stored === 'dark' ? stored : null;
  }

  private crumbsFor(url: string): readonly Crumb[] {
    const [section = 'dashboard'] = (url.split('?')[0] ?? '').split('/').filter(Boolean);
    if (section === 'detail') {
      return [{ label: 'Roster', link: '/roster' }, { label: 'Hero detail' }];
    }
    return [{ label: SECTION_LABELS[section] ?? 'Dashboard' }];
  }
}

import { Component, inject } from '@angular/core';
import { RouterLink, RouterLinkActive, RouterOutlet } from '@angular/router';
import { NgIcon, provideIcons } from '@ng-icons/core';
import {
  lucideLayoutDashboard,
  lucideSettings,
  lucideShieldAlert,
  lucideTarget,
  lucideUserPlus,
  lucideUsers,
} from '@ng-icons/lucide';
import { HlmAvatarImports } from '@spartan-ng/helm/avatar';
import { HlmIconImports } from '@spartan-ng/helm/icon';
import { HlmSidebarImports } from '@spartan-ng/helm/sidebar';
import { AppTopbar } from './ui/app-topbar/app-topbar';
import { AppViewModel } from './app.view-model';

type NavIcon =
  | 'lucideLayoutDashboard'
  | 'lucideUsers'
  | 'lucideTarget'
  | 'lucideShieldAlert'
  | 'lucideUserPlus'
  | 'lucideSettings';

const NAV_ITEMS: readonly { readonly label: string; readonly path: string; readonly icon: NavIcon }[] = [
  { label: 'Dashboard', path: '/dashboard', icon: 'lucideLayoutDashboard' },
  { label: 'Roster', path: '/roster', icon: 'lucideUsers' },
  { label: 'Missions', path: '/missions', icon: 'lucideTarget' },
  { label: 'Threats', path: '/threats', icon: 'lucideShieldAlert' },
  { label: 'Recruit', path: '/recruit', icon: 'lucideUserPlus' },
  { label: 'Settings', path: '/settings', icon: 'lucideSettings' },
];

@Component({
  selector: 'app-root',
  imports: [
    RouterOutlet,
    RouterLink,
    RouterLinkActive,
    NgIcon,
    HlmAvatarImports,
    HlmIconImports,
    HlmSidebarImports,
    AppTopbar,
  ],
  providers: [
    AppViewModel,
    provideIcons({
      lucideLayoutDashboard,
      lucideSettings,
      lucideShieldAlert,
      lucideTarget,
      lucideUserPlus,
      lucideUsers,
    }),
  ],
  templateUrl: './app.html',
  styleUrl: './app.css',
})
export class App {
  protected readonly vm = inject(AppViewModel);
  protected readonly navItems = NAV_ITEMS;
}

import { Routes } from '@angular/router';

export const routes: Routes = [
  { path: '', pathMatch: 'full', redirectTo: 'dashboard' },
  {
    path: 'dashboard',
    loadComponent: () => import('./dashboard/dashboard').then((m) => m.Dashboard),
  },
  {
    path: 'roster',
    loadComponent: () => import('./heroes/heroes').then((m) => m.Heroes),
  },
  { path: 'heroes', redirectTo: 'roster' },
  {
    path: 'detail/:id',
    loadComponent: () => import('./hero-detail/hero-detail').then((m) => m.HeroDetail),
  },
  {
    path: 'missions',
    loadComponent: () => import('./missions/missions').then((m) => m.Missions),
  },
  {
    path: 'threats',
    loadComponent: () => import('./threats/threats').then((m) => m.Threats),
  },
  {
    path: 'recruit',
    loadComponent: () => import('./recruit/recruit').then((m) => m.Recruit),
  },
  {
    path: 'settings',
    loadComponent: () => import('./settings/settings').then((m) => m.Settings),
  },
  { path: '**', redirectTo: 'dashboard' },
];

