import { Directive, input } from '@angular/core';
import { classes } from '@spartan-ng/helm/utils';

// A determinate meter track. The value is a 0 to 100 index, exposed as an ARIA meter.
@Directive({
  selector: '[hlmProgress]',
  host: {
    'data-slot': 'progress',
    role: 'meter',
    'aria-valuemin': '0',
    'aria-valuemax': '100',
    '[attr.aria-valuenow]': 'value()',
  },
})
export class HlmProgress {
  public readonly value = input.required<number>();

  constructor() {
    classes(() => 'relative flex h-2 w-full overflow-hidden rounded-full bg-muted');
  }
}

// The filled part of the track. Its width is bound by the host template, not set here.
@Directive({
  selector: '[hlmProgressIndicator]',
  host: {
    'data-slot': 'progress-indicator',
  },
})
export class HlmProgressIndicator {
  constructor() {
    classes(() => 'h-full rounded-full bg-primary transition-all');
  }
}

